 for(let beat=first;beat<=last+.00001;beat+=step){const y=noteY(beat,g),bar=Math.abs(beat/4-Math.round(beat/4))<1e-5,whole=Math.abs(beat-Math.round(beat))<1e-5;DCSettings.stroke(c,p,DCSettings.keyForBeat(beat),g.left,y,w-g.right,y);if(p.rulerMode==='bar'?bar:whole){c.fillStyle=p.rulerColor;c.fillText(p.rulerMode==='bar'?String(Math.floor(beat/4)+1).padStart(3,'0'):p.beatFormat==='decimal'?beat.toFixed(0):'['+C.beatParts(beat).join(',')+']',g.left-6,y-4);}}
 drawAnalysis(c,g);
 for(const t of ch.timings){const y=noteY(t.beat,g);if(y<0||y>h)continue;DCSettings.stroke(c,p,'bpm',g.left,y,w-g.right,y);c.fillStyle=DCSettings.line(p,'bpm').color;c.textAlign='left';c.font='8px sans-serif';c.fillText(t.bpm+' BPM',g.left+3,y-3);}
 for(const e of ch.effects){if(!('scroll'in e))continue;const y=noteY(C.beatValue(e.beat),g);if(y<0||y>h)continue;DCSettings.stroke(c,p,'effect',g.left,y,w-g.right,y);c.fillStyle=DCSettings.line(p,'effect').color;c.textAlign='right';c.font='8px sans-serif';c.fillText('×'+e.scroll,w-g.right-4,y-3);}
 function drawNote(n,ghost=false){const col=order.indexOf(n.lane),x=g.left+(col+.5)*g.lw,y=noteY(n.beat,g),ey=n.end===null?y:noteY(n.end,g),sz=Math.min(36,g.lw*.72);if(y<-sz&&ey<-sz||y>h+sz&&ey>h+sz)return;c.save();if(ghost)c.globalAlpha=.5;
 if(n.end!==null&&!C.isFake(n)){skin?.drawHold(c,skin.config('note-'+(n.lane+1)).tex2||'changtiao.png',x,y,x,ey,sz*.82);skin?.draw(c,skin.config('note-'+(n.lane+1)).tex3||'guangbiaoc.png',x,ey,sz*.8,sz*.8);}
 const cfg=skin?.config('note-'+(n.lane+1))||{},tex=chordIds.has(n.id)?cfg.tex4||'guangbiaob.png':cfg.tex||'guangbiaoa.png';if(!skin?.draw(c,tex,x,y,sz,sz)){c.fillStyle=palette.note;c.beginPath();c.arc(x,y,sz*.35,0,Math.PI*2);c.fill();}
 if(n.rec&&n.rec.confidence<60&&!n.rec.reviewed){c.strokeStyle='#ff4c66';c.lineWidth=2;c.strokeRect(x-sz/2-4,Math.min(y,ey)-sz/2-4,sz+8,Math.abs(y-ey)+sz+8);c.fillStyle='#ff8e9f';c.font='bold 9px monospace';c.fillText(Math.round(n.rec.confidence),x+sz/2+4,y-5);}if(C.isFake(n)){c.fillStyle='#f5c98c';c.font='bold 8px monospace';c.textAlign='center';c.fillText('F',x,y+sz*.65);}if(selection.has(n.id)){c.strokeStyle=palette.accent;c.lineWidth=1.5;c.setLineDash([3,2]);c.strokeRect(x-sz/2-3,Math.min(y,ey)-sz/2-3,sz+6,Math.abs(y-ey)+sz+6);c.setLineDash([]);}c.restore();}
 for(const n of ch.notes)drawNote(n);
 if(drag?.type==='move'&&drag.result?.ok)for(const n of drag.result.notes)if(drag.result.ids.includes(n.id))drawNote(n,true);
