 const py=noteY(C.timeToBeat(ch,position),g);if(py>=0&&py<=h){DCSettings.stroke(c,p,'preview',g.left-21,py,w-g.right,py);c.fillStyle=DCSettings.line(p,'preview').color;c.beginPath();c.moveTo(g.left-19,py-6);c.lineTo(g.left-7,py);c.lineTo(g.left-19,py+6);c.closePath();c.fill();c.font='7px ui-monospace,monospace';c.textAlign='right';c.fillText('预览',g.left-23,py-5);}
