 const ch=chart(),record=assetRecord(ch.audioName,ch),key=ch.audioName+':'+C.crc32(record.data)+':'+ch.bpm;analysisCacheId=key;const capturedName=ch.audioName,capturedRevision=libraryRevision;beginTask('analysis','⌁ 音频频谱与段落分析');$('analysisBadge').textContent='正在分析';const buffer=audioBuffer,sr=Math.min(44100,buffer.sampleRate),length=Math.ceil(buffer.duration*sr),mono=new Float32Array(length),ratio=buffer.sampleRate/sr;
