function generatorModal(){if(!editableChart())return;if(!audioBuffer){toast('请先导入或恢复音乐');return;}if(task?.type==='generation'){toast('自动写谱正在进行，使用右下角进度面板控制');return;}const saved=session.generator||{level:chart().level,useEffects:true,notesPerSecond:40,seed:20261030,weights:Object.fromEntries(PATTERNS.map((k,i)=>[k,[40,45,25,35,50,20,25,35,30][i]]))};
 const refs=referenceProfiles.map(p=>`<b>Lv.${p.level}</b> ${p.notes} 音符 · ${p.density.toFixed(2)} 音符/拍 · 双押组 ${(p.chordRate*100).toFixed(1)}% · 长按 ${(p.holdRate*100).toFixed(1)}%`).join('<br>');
 openModal(header('✦ 自动写谱实验室')+`<div class="modal-content"><div class="local-engine">● 本地计算引擎 · 无外部 API · 无音频上传</div><p class="modal-copy">根据当前音乐的鼓点、能量和重复片段，结合 Crush BETA(VIP) 的配置统计生成一张新难度。原有难度保留，生成后可以继续编辑。</p><div class="model-card">参考谱面学习结果<br>${refs}<br>提取节奏间隔、键位转移与 8 拍配置块，再按权重重组。目标等级为密度估计，仍需人工试听与定级。</div><div class="two-fields"><label class="field">期望等级<input id="genLevel" type="number" min="1" max="100" step="1" value="${saved.level}"></label><label class="field">生成显示速度<select id="genSpeed"><option value="20">慢 · 20 音符 / 秒</option><option value="40">标准 · 40 音符 / 秒</option><option value="80">快 · 80 音符 / 秒</option></select></label></div><div class="two-fields"><label class="field">随机种子<input id="genSeed" type="number" step="1" value="${saved.seed||20261030}"></label><label class="field">变速演出<select id="genEffects"><option value="yes">融入变速</option><option value="no">不使用变速</option></select></label></div><p class="modal-footnote">融入变速时优先沿用当前谱的 scroll 节点；无节点则按候选段落配置温和倍率。BPM 与音符时刻保持音乐同步。</p><div class="section-caption"><span>配置权重 · 0 为关闭</span><span>按 8 拍片段分配</span></div><div class="weight-grid">${PATTERNS.map((name,i)=>`<label class="range-field">${name}<output id="weightOut${i}">${saved.weights?.[name]??30}</output><input id="weight${i}" type="range" min="0" max="100" value="${saved.weights?.[name]??30}" data-pattern="${i}"></label>`).join('')}</div><label class="check-line"><input id="genMulti" type="checkbox"> 允许多押（超过双手限制，默认关闭）</label><label class="field">生成前的节拍校准<select id="genTiming"><option value="measure">重新分析 BPM / 变 BPM 与 Offset（推荐）</option><option value="current">使用已人工校准的 BPMList / Offset</option></select></label><p class="field-hint">测量后先审核候选表，再生成新难度；当前原谱保留。</p><div class="modal-actions"><button id="genStart" class="primary">分析音频并开始生成 →</button></div><p class="modal-footnote">过程显示真实进度，可暂停或取消。取消会保留已写入的新难度草稿；撤销可移除本次生成。所有分析在浏览器本机执行，不调用远程 AI。</p></div>`);
 $('genSpeed').value=saved.notesPerSecond||40;$('genEffects').value=saved.useEffects?'yes':'no';
 function collect(){return{allowMulti:$('genMulti').checked,maxChord:3,timingMode:$('genTiming').value,level:C.clamp(+$('genLevel').value||1,1,100),useEffects:$('genEffects').value==='yes',notesPerSecond:+$('genSpeed').value,seed:+$('genSeed').value||20261030,sensitivity:settings().sensitivity,weights:Object.fromEntries(PATTERNS.map((k,i)=>[k,+$('weight'+i).value]))};}
 for(const el of [...$$('[data-pattern]'),$('genLevel'),$('genSpeed'),$('genSeed'),$('genEffects'),$('genMulti')])el.oninput=()=>{PATTERNS.forEach((k,i)=>$('weightOut'+i).textContent=$('weight'+i).value);session.generator=collect();save();};
 $('genStart').onclick=async()=>{const options=collect();if(!Object.values(options.weights).some(n=>n>0)){toast('至少设置一种非零配置权重');return;}session.generator=options;save();$('modal').close();try{if(options.timingMode!=='current')await measureTiming({kind:'generate',options,chartId:chart().id});else await generate(options);}catch(e){if(!e.message.includes('取消'))toast('生成未完成：'+e.message);}};
}
$('generateBtn').onclick=generatorModal;
async function generate(options,timing=null){pause();if(!analysis)await runAnalysis(false);const original=timing?C.applyTiming(chart(),timing):chart(),plan=C.generatePlan(original,{...analysis,gridOnsets:DCRhythm.gridOnsets(original,analysis,settings())},referenceProfiles,{...options,freqLow:settings().freqLow,freqHigh:settings().freqHigh});if(!plan.notes.length)throw Error('未检测到足够鼓点，请提高灵敏度或检查音频');const job=beginTask('generation','✦ 自动写谱 · 逐批写入');beforeChange();const next=C.validateChart({...C.clone(original),id:C.uid(),filename:'generated-'+Date.now()+'.mc',name:`Dance Cube Lv.${options.level} · AUTO`,level:options.level,tier:C.inferTier(options.level),notes:[],effects:plan.effects,generated:{referenceLevel:plan.referenceLevel,options,patterns:plan.patterns}});if(next.rawMC?.meta)next.rawMC.meta.id=0;session.charts.push(next);session.activeChartId=next.id;selection.clear();syncUI();rebuildCaches();const count=plan.notes.length,batch=Math.max(1,Math.round(options.notesPerSecond/20));let i=0,lastPersist=0;
 while(i<count&&!job.cancelled){while(job.paused&&!job.cancelled)await new Promise(r=>setTimeout(r,60));if(job.cancelled)break;const added=plan.notes.slice(i,i+batch);next.notes.push(...added);i+=added.length;rebuildCaches();const last=added.at(-1);position=Math.max(0,C.beatToTime(next,last.beat)-.08);const g=geometry();session.view.bottomBeat=last.beat-(g.h-g.h*.55)/g.px;$('noteCount').textContent=next.notes.length.toLocaleString();$('holdCount').textContent=next.notes.filter(n=>n.end!==null).length;updateTransport();setProgress(i/count*100,`已写入 ${i} / ${count} 音符 · ${options.notesPerSecond} 音符/秒 · 参考 Lv.${plan.referenceLevel}`);if(performance.now()-lastPersist>800){flushSave();lastPersist=performance.now();}await new Promise(r=>setTimeout(r,50));}
 const cancelled=job.cancelled;completeTask(cancelled?`已取消 · 保留 ${next.notes.length} 个音符的草稿，可继续编辑或撤销`:`生成完成 · ${next.notes.length} 音符 · 已创建新难度，可继续编辑`,cancelled?i/count*100:100);position=Math.max(0,C.beatToTime(next,next.notes[0]?.beat||0)-.4);session.view.bottomBeat=null;changed();flushSave();setTool('select');toast(cancelled?'生成已取消，已保留当前草稿':'新难度已生成，可以试听、框选和继续修改');}
$('timingBtn').onclick=()=>{if(!editableChart())return;if(task?.type==='generation'){toast('生成完成后可以编辑变速');return;}timingModal();};
function mutationAllowed(){if(deletionBusy){toast('正在清理本机缓存，请稍候');return false;}if(task?.type==='generation'||task?.type==='timing'){toast('请先完成或取消自动写谱');return false;}return true;}
for(const id of ['title','artist'])$(id).oninput=e=>{if(!ready)return;session.song[id]=e.target.value;activeSong().song=session.song;updateSongTitles();for(const key of ['songHeading','stageTitle','waveTitle'])if(id==='title')$(key).textContent=e.target.value;if(id==='artist')$('artistHeading').textContent=e.target.value;save();};
for(const [id,key]of [['creator','creator'],['chartName','name']])$(id).onchange=e=>{if(!mutationAllowed()||!editableChart()){syncUI();return;}beforeChange();chart()[key]=e.target.value;changed();};
for(const id of ['level','tier','bpm','offset','audioBeat'])$(id).onchange=e=>{if(!mutationAllowed()||!editableChart()){syncUI();return;}let value;try{value=id==='audioBeat'?C.parseBeat(e.target.value):+e.target.value;}catch(err){toast(err.message);syncUI();return;}if(id==='level'&&C.levelValue(e.target.value)===null||!Number.isFinite(value)||id==='bpm'&&(value<=0||value>2000)||id==='level'&&(value<0||value>100)||id==='audioBeat'&&value<0){toast('请输入有效数值');syncUI();return;}pause();beforeChange();const ch=chart();if(id==='level'&&/^Dance Cube Lv\.[\d.]+(?: · AUTO)?$/.test(ch.name))ch.name=ch.name.replace(/Lv\.[\d.]+/,'Lv.'+value);ch[id]=value;if(id==='level')ch.showLevelUnknown=false;if(id==='tier'&&isShow())ch.showSlot=101+value;changed();};
$$('.theme-group button').forEach(b=>b.onclick=()=>{settings().theme=b.dataset.theme;applyTheme();save();drawTimeline();});
for(const id of ['snap','layout','noteSpeed','brightness','freqLow','freqHigh','waveGain','sensitivity'])$(id).oninput=e=>{settings()[id]=id==='layout'?e.target.value:+e.target.value;if(id==='brightness')$('brightnessValue').textContent=e.target.value+'%';if(id==='waveGain')$('gainValue').textContent=e.target.value+' dB';if(id==='sensitivity')$('sensitivityValue').textContent=e.target.value+'%';if(['freqLow','freqHigh','sensitivity'].includes(id)){normalizeFrequencyRange(id);refreshGridOnsets();}if(id==='noteSpeed'){$('noteSpeedValue').textContent=Number(e.target.value).toFixed(1);rebuildCaches();updateTransport();}drawDirty=true;drawTimeline();save();};
$('zoom').oninput=e=>{const g=geometry(),lineY=noteY(C.timeToBeat(chart(),position),g),at=screenBeat(C.clamp(lineY,0,g.h),g);settings().zoom=+e.target.value;const ng=geometry();session.view.bottomBeat=at-(ng.h-C.clamp(lineY,0,g.h))/ng.px;$('zoomValue').textContent=e.target.value+'%';drawDirty=true;save();};
$('lineHeight').oninput=e=>{if(playing)pause();const ratio=+e.target.value/100,g=geometry();settings().lineRatio=ratio;position=C.clamp(C.beatToTime(chart(),Math.max(-16,screenBeat(g.h*ratio,g))),minTime(),totalSeconds());$('lineValue').textContent=e.target.value+'%';drawDirty=true;updateTransport();save();};
for(const id of ['follow','auto','useBackground','waveform','frequency','sections','repeats','spectrum','onsets'])$(id).onchange=e=>{settings()[id]=e.target.checked;drawDirty=true;drawTimeline();save();};
$('rate').onchange=e=>{const was=playing;pause();settings().rate=+e.target.value;save();if(was)play();};$('volume').oninput=e=>{settings().volume=+e.target.value;if(masterGain)masterGain.gain.value=+e.target.value/100;save();};
$('metronomeBtn').onclick=()=>{const was=playing;pause();settings().beatSound.enabled=!settings().beatSound.enabled;settings().metronome=settings().beatSound.enabled;syncUI();save();if(was)play();};$('playBtn').onclick=play;$('stopBtn').onclick=()=>{pause();seek(minTime(),true);};$('restartBtn').onclick=restart;$('timelineCanvas').onclick=e=>{if(task?.type==='generation')return;const r=e.target.getBoundingClientRect(),v=timelineView();seek(v.start+(e.clientX-r.left)/r.width*v.span,true);};
$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('stage').requestFullscreen();}catch(e){toast('当前浏览器不支持全屏');}};
$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('undoBtn').onclick=undo;$('redoBtn').onclick=redo;$('copyBtn').onclick=copySelection;$('pasteBtn').onclick=()=>mutationAllowed()&&pasteSelection();$('deleteBtn').onclick=()=>mutationAllowed()&&deleteNotes();
$$('[data-mirror]').forEach(b=>b.onclick=()=>{if(!mutationAllowed())return;const was=new Set(selection);if($('mirrorScope').value==='all')selection=new Set(allEntries().map(n=>n.id));if(!selection.size){toast('请先框选音符，或将范围改为全谱镜像');return;}const ok=applyTransform({mirror:b.dataset.mirror});if($('mirrorScope').value==='all')selection=was;updateSelectionUI();if(ok)toast('已应用'+b.textContent+'镜像 · Ctrl+Z 可撤销');});

