async function preparePreview(){if(settings().preload==='off'||detectedRefresh&&detectedRefresh<100){updatePreloadStatus();return;}if(preloadPromise)return preloadPromise;const index=previewIndex,generation=preloadGeneration,start=settings().preload==='all'?minTime():Math.max(minTime(),position-10),end=settings().preload==='all'?totalSeconds():Math.min(totalSeconds(),position+10),job=async()=>{if(settings().preload==='near')for(const key of index.buckets.keys())if(key<Math.floor(start*4)||key>Math.ceil(end*4))index.buckets.delete(key);updatePreloadStatus(1,0,0,'加载谱面索引…');await index.preload(start,end,async()=>{await new Promise(r=>setTimeout(r,0));if(generation!==preloadGeneration)throw Error('谱面已变更，重新加载预览缓存');},p=>updatePreloadStatus(1,p,0,`谱面 ${Math.round(p*100)}% · ${fmt(start)}—${fmt(end)}`));if(showEngine){const result=await DCShowPreview.loadSprites();if(generation!==preloadGeneration)throw Error('秀谱已切换，预览缓存已失效');updatePreloadStatus(1,1,0,'官方默认素材 '+result.loaded+'/'+result.total+' · 正在加载当前皮肤特效…');}const names=DCPreview.skinFrames(skin);let i=0;for(const name of names){if(generation!==preloadGeneration)throw Error('谱面变更，缓存需要重新加载');await skin.frame(name);i++;if(i%8===0){updatePreloadStatus(1,1,i/names.length,`图集 / 打击帧 ${i}/${names.length}`);await new Promise(r=>setTimeout(r,0));}}preloadedWindow={start,end,generation};updatePreloadStatus(1,1,1,`已加载：索引、音符与皮肤 · ${fmt(start)}—${fmt(end)}`);};preloadPromise=job().finally(()=>preloadPromise=null);return preloadPromise;}
function probeRefreshRate(){const values=[],started=performance.now();let last=0;function sample(t){if(document.hidden){requestAnimationFrame(sample);return;}if(last&&t-last<100)values.push(t-last);last=t;if(values.length<75&&performance.now()-started<6500){requestAnimationFrame(sample);return;}if(!values.length)values.push(1000/60);values.sort((a,b)=>a-b);detectedRefresh=Math.round(1000/values[Math.floor(values.length*.2)]);if(detectedRefresh<100&&settings().preload!=='off'){settings().preload='off';updatePreloadStatus();save();}}requestAnimationFrame(sample);}
