function exportModal(){if(!mutationAllowed())return;DCProject.sync(session);openModal(header('导出谱面包')+`<div class="modal-content"><p class="modal-copy">ZIP 是本网页的通用格式，保留假键与 MCZ 原有的谱面 / 音乐 / 背景结构。MCZ 供 Malody 使用；TXT 供舞立方机台使用。</p><form id="packageExportForm"><div class="two-fields"><label class="field">格式<select id="exportFormat"><option value="zip">① ZIP · 网页原生格式（默认）</option><option value="mcz">② MCZ · Malody 格式</option><option value="txt">③ TXT · 舞立方机台包</option></select></label><label class="field">导出范围<select id="exportScope"><option value="song">当前歌曲 · 全部难度</option><option value="chart">当前难度</option><option value="library">歌曲库 · 全部歌曲</option></select></label></div><label class="check-line" id="txtMergeLabel"><input id="txtMerge" type="checkbox" checked> 合并同类项：同起同止的双押 / 多押显示黄键</label><p id="txtExportInfo" class="field-hint" hidden>TXT 按基准 BPM 折算实际时刻：经典保留 2 位小数，秀谱最多 8 位，滑条续段保持相邻。所有 TXT 一次打包并附带回读 JSON；JSON 不上传至机台。TXT 不含音频与背景，秀谱 SV 默认关闭。</p><div id="showSVOptions" class="notice" hidden><p>舞立方官方秀谱不支持变速。TXT 默认不导出秀谱 SV；需要保留完整 effect 请保存 ZIP。</p><label class="check-line"><input id="forceShowSV" type="checkbox"> 我已了解官方不支持秀谱变速，仍强制输出秀谱 -sv.txt</label></div><p id="multiPressHint" class="field-hint" hidden>提示：本次导出含 3 押或更多同时按键且等级不为 0 的谱面。玩家常用 0 级标识娱乐 / 整活 / 多押谱，请自行确认定级。</p><div id="mczShowWarning" class="notice" hidden><p>当前范围含秀谱。MCZ仅保留外框普通单点/长条及可表达的时间和SV，内框、滑条及旋转会被舍弃；原始数据备份不保证经Malody重存保留。</p><label><input id="acceptShowLoss" type="checkbox"> 我了解并接受经典六键投影损失</label></div><div id="mczFakeWarning" class="notice" hidden><p>当前范围包含假键（0 长度长条）。Malody 不支持这种写法，打开后再保存会覆盖假键配置。</p><label><input id="acceptFakeLoss" type="checkbox"> 我已了解，仍继续导出 MCZ</label></div><div class="modal-actions"><button type="submit" class="primary">准备一个下载包</button></div></form><div class="button-row"><button id="backupWorkspaceJSON">导出编辑状态 JSON（不含媒体）</button></div></div>`);
 $('exportFormat').value=settings().exportFormat||'zip';function selected(){return $('exportScope').value==='library'?session.songs:$('exportScope').value==='chart'?[{...activeSong(),charts:[chart()]}]:[activeSong()];}function update(){const format=$('exportFormat').value;$('showSVOptions').hidden=format!=='txt'||!selected().some(s=>s.charts.some(c=>c.mode==='show'));$('multiPressHint').hidden=!selected().some(s=>s.charts.some(c=>c.level!==0&&DCShow.hasMultiPress(c)));const fake=selected().some(s=>s.charts.some(c=>c.mode==='show'?c.showStats.fake>0:c.notes.some(C.isFake)));$('txtMergeLabel').hidden=format!=='txt';$('txtExportInfo').hidden=format!=='txt';$('mczFakeWarning').hidden=format!=='mcz'||!fake;$('mczShowWarning').hidden=format!=='mcz'||!selected().some(s=>s.charts.some(c=>c.mode==='show'));}for(const id of ['exportFormat','exportScope'])$(id).onchange=update;update();
 $('packageExportForm').onsubmit=e=>{e.preventDefault();try{const format=$('exportFormat').value,list=selected(),scope=$('exportScope').value;if(format==='mcz'&&list.some(s=>s.charts.some(c=>c.mode==='show'?c.showStats.fake>0:c.notes.some(C.isFake)))&&!$('acceptFakeLoss').checked){toast('请先确认 Malody 会覆盖假键的提示');return;}if(format==='mcz'&&list.some(s=>s.charts.some(c=>c.mode==='show'))&&!$('acceptShowLoss').checked){toast('请先确认秀谱转换为经典MCZ时会丢失特殊元素');return;}const files=[],time=DCProject.timestamp(),txtEntries=item=>{const classic=item.charts.filter(c=>c.mode!=='show'),shows=item.charts.filter(c=>c.mode==='show'),out=[];if(classic.length)out.push(...DCFormats.txtPack(item.song,classic,{merge:$('txtMerge').checked}).files);if(shows.length)out.push(...DCShow.txtPack(DCShow.manifest(item.song,shows),songAssets(item).map(([name,value])=>({name,data:value.data})),{includeSV:$('forceShowSV').checked,merge:$('txtMerge').checked}));return out;};if(format==='txt'){if(list.length===1)files.push(...txtEntries(list[0]));else for(const item of list){const prefix=DCProject.fileName(item.song.title)+'-'+item.id.slice(0,6)+'/';files.push(...txtEntries(item).map(f=>({...f,name:prefix+f.name})));}download(C.zipStore(files),(scope==='library'?'歌曲库':safeName())+'-'+time+'-txtpack.zip');}else{if(list.length===1)files.push(...songEntries(list[0],list[0].charts,'',format));else{const manifest={format:'dc-library-1',songs:[]};for(const item of list){const folder=DCProject.fileName(item.song.title)+'-'+item.id.slice(0,6)+'/';files.push(...songEntries(item,item.charts,folder,format));manifest.songs.push({folder,song:item.song});}files.push({name:'dc-library.json',data:new TextEncoder().encode(JSON.stringify(manifest,null,2))});}download(C.zipStore(files),(scope==='library'?'歌曲库':safeName())+'-'+time+'.'+format);}settings().exportFormat=format;save();toast('已准备下载包；请点击下载入口保存');}catch(err){toast('导出失败：'+err.message);}};$('backupWorkspaceJSON').onclick=()=>{DCProject.sync(session);download(JSON.stringify(session,null,2),'DanceCube_Workspace-'+DCProject.timestamp()+'.json','application/json');};}
function text(data){return new TextDecoder().decode(data);}
function requestTXTparameters(files,title){return new Promise((resolve,reject)=>{let done=false;openModal(header('TXT 导入：补充时间参数')+`<div class="modal-content"><p class="modal-copy">纯 TXT 没有 BPM、Offset、原始变 BPM 或歌曲资料。请填写转换时使用的基准 BPM 与第一个音符的音频时刻。${esc(title)}</p><form id="txtImportParams"><label class="field">歌曲名<input id="txtImportTitle" value="${esc(title||'Untitled')}" required></label><div class="two-fields"><label class="field">基准 BPM · 必填<input id="txtImportBpm" type="number" min="0.01" max="2000" step="any" required></label><label class="field">首音符时间 · 秒<input id="txtImportStart" type="number" step="any" value="0" required></label></div><label class="field">谱面类型<select id="txtImportType"><option value="classic">经典 6K</option><option value="show">秀谱（含 A–F / 滑条）</option></select></label><label class="field">等级<input id="txtImportLevel" type="number" min="0" max="100" value="12" required></label><div class="modal-actions"><button type="submit" class="primary">导入 TXT 谱面</button></div></form></div>`);const onClose=()=>{if(!done){done=true;reject(Error('已取消 TXT 导入'));}$('modal').removeEventListener('close',onClose);};$('modal').addEventListener('close',onClose);$('txtImportType').value=files.some(f=>/\.txt$/i.test(f.name)&&!/-sv\.txt$/i.test(f.name)&&/^(?:[1-6A-F]*[A-F][1-6A-F]*-|[1-6]+\s*[LR]\s*\d)/m.test(text(f.data)))?'show':'classic';$('txtImportParams').onsubmit=e=>{e.preventDefault();const bpm=+$('txtImportBpm').value,startTime=+$('txtImportStart').value;if(!(bpm>0&&bpm<=2000)||!Number.isFinite(startTime))return;done=true;resolve({bpm,startTime,title:$('txtImportTitle').value,level:+$('txtImportLevel').value,mode:$('txtImportType').value});$('modal').close();};});}
async function bundleFromFiles(files,title){const libraryFile=files.find(f=>f.name==='dc-library.json');if(libraryFile){const m=JSON.parse(text(libraryFile.data));if(m.format!=='dc-library-1')throw Error('歌曲库清单无效');const out=[];for(const item of m.songs){const subset=files.filter(f=>f.name.startsWith(item.folder)).map(f=>({...f,name:f.name.slice(item.folder.length)}));out.push(...await bundleFromFiles(subset,item.song.title));}return out;}let showBundle=null;if(files.some(f=>f.name==='dc-show.json')){const parsed=DCShow.readPackage(files);showBundle={song:parsed.song,charts:parsed.charts.map(DCShow.carrier),files:files.filter(f=>!/\.mc$/i.test(f.name))};}const mcFiles=files.filter(f=>/\.mc$/i.test(f.name));if(mcFiles.length){const manifest=files.find(f=>f.name==='dc-library.json');if(manifest){const m=JSON.parse(text(manifest.data));if(m.format!=='dc-library-1')throw Error('歌曲库清单无效');const out=[];for(const item of m.songs){const subset=files.filter(f=>f.name.startsWith(item.folder)).map(f=>({...f,name:f.name.slice(item.folder.length)}));out.push(...await bundleFromFiles(subset,item.song.title));}return out;}
 const groups=new Map();for(const f of mcFiles){const mc=JSON.parse(text(f.data)),ch=C.fromMC(mc,f.name),song={title:mc.meta?.song?.title||title||'Untitled',artist:mc.meta?.song?.artist||''},key=JSON.stringify([song.title,song.artist]);if(!groups.has(key))groups.set(key,{song,charts:[],files:files.filter(f=>!/\.mc$/i.test(f.name))});groups.get(key).charts.push(ch);}if(showBundle){const key=JSON.stringify([showBundle.song.title,showBundle.song.artist]);if(groups.has(key))groups.get(key).charts.push(...showBundle.charts);else groups.set(key,showBundle);}return[...groups.values()];}
 const manifestFiles=files.filter(f=>/(^|\/)dc-txtpack.json$/i.test(f.name));if(manifestFiles.length){const parsedBundles=manifestFiles.map(m=>{const prefix=m.name.slice(0,m.name.lastIndexOf('/')+1),subset=files.filter(f=>f.name.startsWith(prefix)).map(f=>({...f,name:f.name.slice(prefix.length)})),parsed=DCFormats.readTXTpack(subset);return{...parsed,files:[]};});if(showBundle){const found=parsedBundles.find(bundle=>bundle.song.title===showBundle.song.title&&bundle.song.artist===showBundle.song.artist);if(found){found.charts.push(...showBundle.charts);found.files=showBundle.files;}else parsedBundles.push(showBundle);}return parsedBundles;}if(showBundle)return[showBundle];
 if(files.some(f=>/\.txt$/i.test(f.name))){const options=await requestTXTparameters(files,title);if(options.mode==='show'){const charts=files.filter(f=>/\.txt$/i.test(f.name)&&!/-sv\.txt$/i.test(f.name)).map(f=>DCShow.carrier({...DCShow.parseTXT(text(f.data),{bpm:options.bpm,beginSeconds:options.startTime,slot:105,level:options.level}),name:f.name.replace(/\.txt$/i,'')}));return[{song:{title:options.title,artist:''},charts,files:[]}];}const parsed=DCFormats.readTXTpack(files,options);return[{...parsed,files:[]}];}throw Error('ZIP 内没有 MC 谱面或 TXT 谱面');}
async function handleImports(fileList){if(!mutationAllowed())return;pause();cancelAnalysis();const files=[...fileList],bundles=[],errors=[];if(files.length&&files.every(f=>/\.txt$/i.test(f.name))){try{bundles.push(...await bundleFromFiles(await Promise.all(files.map(async f=>({name:f.name,data:new Uint8Array(await f.arrayBuffer())}))),files[0].name.replace(/\.txt$/i,'')));}catch(e){toast(e.message);return;}}else for(const f of files){try{if(f.size>150*1024*1024)throw Error('文件超过 150 MB');if(/\.(zip|mcz)$/i.test(f.name)){bundles.push(...await bundleFromFiles(await C.unzip(await f.arrayBuffer()),f.name.replace(/\.[^.]+$/,'')));}else if(f.type.startsWith('audio/')||/\.(mp3|ogg|wav|flac|m4a)$/i.test(f.name)){const data=new Uint8Array(await f.arrayBuffer());await getAudio().decodeAudioData(data.slice().buffer);const name=f.name.replace(/[\\/]/g,'_'),ch=C.validateChart({id:C.uid(),name:'Dance Cube Lv.12',level:12,bpm:120,offset:0,audioBeat:0,audioName:name,backgroundName:'',timings:[],effects:[],notes:[]});bundles.push({song:{title:name.replace(/\.[^.]+$/,''),artist:''},charts:[ch],files:[{name,data}],newAudio:true});}else if(/\.txt$/i.test(f.name)){bundles.push(...await bundleFromFiles([{name:f.name,data:new Uint8Array(await f.arrayBuffer())}],f.name.replace(/\.txt$/i,'')));}else{const data=JSON.parse(await f.text());if(data.format==='dc-studio-2'||data.format==='dc-studio-3'){const next=validateSession(data);for(const item of next.songs)bundles.push({song:item.song,charts:item.charts,files:[],missingAssets:true});}else if(data.format==='dc-show-chart-2'){const ch=DCShow.carrier(data);bundles.push({song:{title:data.title||f.name.replace(/\.json$/i,''),artist:''},charts:[ch],files:[]});}else{const ch=C.fromMC(data,f.name);bundles.push({song:{title:data.meta?.song?.title||f.name,artist:data.meta?.song?.artist||''},charts:[ch],files:[]});}}}catch(e){errors.push(f.name+'：'+e.message);}}
 if(!bundles.length){if(errors.length)toast(errors.join('；'));return;}beforeChange();DCProject.sync(session);for(const bundle of bundles){const id=C.uid(),prefix='song-'+id+'/',charts=bundle.charts.map(c=>C.validateChart({...c,id:C.uid()}));for(const f of bundle.files)assets.set(prefix+f.name,{data:f.data,mime:mime(f.name)});session.songs.push({id,song:bundle.song,charts,activeChartId:charts[0].id,view:{bottomBeat:null,position:0},assetPrefix:prefix,expanded:true,chartExpanded:{}});nativeDirty.add(id);}const added=session.songs.at(-bundles.length);DCProject.activate(session,added.id);selection.clear();clipboard=[];position=0;loadedAudioName='';audioBuffer=null;analysis=null;gridSignature='';librarySignature='';rebuildCaches();syncUI();await persistAssets();await loadChartAssets();changed();flushSave();toast(`已添加 ${bundles.length} 首歌曲，原歌曲保留`+(errors.length?'；部分文件未导入：'+errors.join('；'):''));if(bundles.length===1&&bundles[0].newAudio)creationWizard(true);return bundles.length;}
function newSongModal(){if(!mutationAllowed())return;openModal(header('新建歌曲')+`<div class="modal-content"><form id="newSongForm"><label class="field">歌曲名<input id="newSongTitle" required maxlength="120"></label><label class="field">艺术家<input id="newSongArtist"></label><div class="two-fields"><label class="field">第一段 BPM · 必填<input id="newSongBpm" type="number" min="0.01" max="2000" step="any" required></label><label class="field">等级<input id="newSongLevel" type="number" min="0" max="100" value="12" required></label></div><p class="field-hint">Offset 初始为 0；创建后导入音乐并选择自动测量校准。也可直接使用“添加多个谱包 / 音乐”。</p><div class="modal-actions"><button type="submit" class="primary">创建歌曲</button></div></form></div>`);$('newSongForm').onsubmit=async e=>{e.preventDefault();const bpm=+$('newSongBpm').value,level=+$('newSongLevel').value;if(!(bpm>0&&bpm<=2000))return;beforeChange();DCProject.sync(session);const id=C.uid(),ch=C.validateChart({id:C.uid(),name:'Dance Cube Lv.'+level,level,bpm,notes:[],timings:[],effects:[],offset:0});session.songs.push({id,song:{title:$('newSongTitle').value,artist:$('newSongArtist').value},charts:[ch],activeChartId:ch.id,view:{position:0,bottomBeat:null},expanded:true,chartExpanded:{},assetPrefix:'song-'+id+'/'});$('modal').close();await switchSong(id);nativeDirty.add(id);changed();};}
$('showBackground').onchange=event=>{settings().showUseBackground=event.target.checked;drawDirty=true;save();};$('settingsBtn').onclick=settingsModal;$('userGuideBtn').onclick=()=>docsModal('README.md','用户指南');$('devGuideBtn').onclick=()=>docsModal('DEVELOPMENT.md','开发文档');$('planBtn').onclick=()=>docsModal('plan.MD','计划');$('legalBtn').onclick=()=>docsModal('LEGAL.md','法律声明与数据说明');$('onsetListBtn').onclick=onsetListModal;$('newSongBtn').onclick=newSongModal;$('mergeSongsBtn').onclick=mergeSongsModal;$('addSongsBtn').onclick=()=>{if(mutationAllowed())$('chartFile').click();};$('importBtn').onclick=()=>{if(mutationAllowed())$('chartFile').click();};$('exportBtn').onclick=exportModal;$('chartFile').onchange=e=>{const files=[...e.target.files];e.target.value='';handleImports(files).catch(err=>toast('导入失败：'+err.message));};
$('timelineZoom').oninput=e=>{const old=timelineView(),anchor=old.start+old.span/2;settings().timelineZoom=+e.target.value;const next=timelineView();settings().timelinePan=next.duration>next.span?C.clamp((anchor-next.span/2)/(next.duration-next.span)*1000,0,1000):0;syncExtraUI();drawTimeline();save();};$('timelinePan').oninput=e=>{settings().timelinePan=+e.target.value;drawTimeline();save();};
$('panModeBtn').onclick=()=>{panMode=!panMode;$('panModeBtn').classList.toggle('active',panMode);$('panModeBtn').textContent=panMode?'✋ 浏览中':'✋ 拖动浏览';};for(const[id,dir]of [['viewPrevBtn',-1],['viewNextBtn',1]])$(id).onclick=()=>{const g=geometry();session.view.bottomBeat=C.clamp(viewBottom()+dir*g.h/g.px*.75,minBottom(),maxBottom());drawDirty=true;save();};$$('[data-nudge]').forEach(b=>b.onclick=()=>{if(!mutationAllowed()||!selection.size)return;applyTransform({deltaColumn:b.dataset.nudge==='left'?-1:b.dataset.nudge==='right'?1:0,deltaBeat:b.dataset.nudge==='up'?1/settings().snap:b.dataset.nudge==='down'?-1/settings().snap:0});});$$('[data-mobile-tab]').forEach(b=>b.onclick=()=>{settings().mobilePanel=b.dataset.mobileTab;applyDeviceLayout();drawDirty=true;drawTimeline();save();});$('mobileLibraryBtn').onclick=()=>document.documentElement.classList.toggle('show-library');
$('jumpBtn').onclick=()=>{openModal(header('定位到 MC 大拍 / 小节')+`<div class="modal-content"><form id="jumpForm"><div class="two-fields">${beatInput(C.timeToBeat(chart(),position),'jumpBeat','MC 大拍或小数拍')}<label class="field">小节（从 1 开始）<input id="jumpBar" type="number" min="-3" step="1" value="${Math.max(-3,Math.floor(C.timeToBeat(chart(),position)/4)+1)}"></label></div><div class="modal-actions"><button type="submit" class="primary">定位</button></div></form></div>`);$('jumpBar').oninput=()=>$('jumpBeat').value='['+C.beatParts(Math.max(-16,(+$('jumpBar').value-1)*4)).join(',')+']';$('jumpForm').onsubmit=e=>{e.preventDefault();try{seek(C.beatToTime(chart(),inputBeat('jumpBeat')),true);$('modal').close();}catch(err){toast(err.message);}};};

$('recipesBtn').onclick=()=>{if(!ready||!editableChart())return;DCRecipeUI.open({esc,header,openModal,toast,download,read:()=>dbGet('recipes'),write:records=>dbPut([['recipes',records]]),selection:()=>C.clone(chart().notes.filter(n=>selection.has(n.id))),songTitle:()=>session.song.title,source:()=>({title:session.song.title,chart:chart().name,bpm:chart().bpm}),currentBeat:()=>{const beat=C.timeToBeat(chart(),position);if(beat<0)throw Error('预卷区域不能插入配方');return Math.round(beat*settings().snap)/settings().snap;},insert:items=>{if(!mutationAllowed())throw Error('请先完成当前任务');if(chart().notes.length+items.length>200000)throw Error('谱面超过 200000 音符上限');if(items.some(n=>n.beat<0))throw Error('预卷区域不能插入配方');if(DCRecipes.collisions(chart().notes,items))throw Error('目标位置或重复边界有音符重叠，请调整拍位或空拍');beforeChange();chart().notes.push(...items);chart().notes.sort((a,b)=>a.beat-b.beat||a.lane-b.lane);chart().beats=Math.max(chart().beats,...items.map(n=>(n.end??n.beat)+8));selection=new Set(items.map(n=>n.id));changed();}}).catch(e=>toast(e.message));};
DCAccount.init({esc,header,openModal,toast,legal:()=>docsModal('LEGAL.md','法律声明与数据说明'),previewCursor:record=>DCWebSettings.previewCursor(record),canEdit:()=>ready&&mutationAllowed(),download,loadPackage:(blob,name)=>handleImports([new File([blob],name,{type:'application/zip'})])});
window.DC={get state(){return session?C.clone(session):null;},get currentChart(){return session?C.clone(chart()):null;},get position(){return position;},get playing(){return playing;},get analysis(){return analysis;},get selection(){return[...selection];},get task(){return task?{type:task.type,paused:task.paused}:null;},get assetNames(){return[...assets.keys()];},get audioDuration(){return audioBuffer?.duration||0;},get skinTitle(){return skin?.title;},get timingCandidate(){return pendingTiming?C.clone(pendingTiming):null;},toMC:()=>C.toMC(chart(),session.song),fromMC:C.fromMC,beatToTime:b=>C.beatToTime(chart(),b),timeToBeat:t=>C.timeToBeat(chart(),t),zipStore:C.zipStore,unzip:C.unzip,seek,flushSave,generatorModal,exportModal,runAnalysis};
boot();

/* REC Lab imports a new difficulty atomically; never edits the source charts. */
function recReviewHooks(){return{esc,header,open:openModal,toast,chart,update:fn=>{if(!mutationAllowed())throw Error('请先完成当前编辑任务');const next=C.validateChart(fn(C.clone(chart())));beforeChange();Object.assign(chart(),next);changed();},jump:id=>{const n=chart().notes.find(n=>n.id===id);if(!n)return;selection=new Set([id]);seek(C.beatToTime(chart(),n.beat),true);setTool('select');updateSelectionUI();drawDirty=true;}};}
$('recReviewBtn').onclick=()=>DCRecLab.review(recReviewHooks());
$('recLabBtn').onclick=()=>{if(!ready||!mutationAllowed())return;pause();DCRecLab.open({esc,header,open:openModal,toast,currentSong:()=>session.activeSongId,songs:()=>session.songs.map(s=>({id:s.id,title:s.song.title})),audio:id=>{const item=session.songs.find(s=>s.id===id);if(!item)return null;const media=new Map(songAssets(item));for(const ch of item.charts){if(!ch.audioName)continue;const dir=(ch.filename||'').includes('/')?ch.filename.slice(0,ch.filename.lastIndexOf('/')+1):'',name=media.has(dir+ch.audioName)?dir+ch.audioName:ch.audioName,record=media.get(name);if(record)return{...record,name,relativeName:name,scopeSong:id,backgroundName:ch.backgroundName};}return null;},decode:bytes=>getAudio().decodeAudioData(bytes.slice().buffer),commit:async result=>{if(!mutationAllowed())throw Error('请先完成当前任务');DCProject.sync(session);const next=C.clone(session),nextAssets=new Map(assets),ch=C.validateChart(result.chart);let item=next.songs.find(s=>s.id===result.songId);if(result.songId!=='new'&&!item)throw Error('目标歌曲已被移除，请重新选择');if(!item){const id=C.uid();item={id,song:{title:result.title,artist:''},charts:[],assetPrefix:'song-'+id+'/',view:{position:0,bottomBeat:null},expanded:true,chartExpanded:{}};next.songs.push(item);}let audioName;if(result.audio.scopeSong===item.id&&nextAssets.has(item.assetPrefix+result.audio.relativeName)){audioName=result.audio.relativeName;ch.backgroundName=result.audio.backgroundName||'';}else{const ext=result.audio.name.match(/\.[a-z0-9]{1,8}$/i)?.[0]||'.audio';audioName='rec-audio-'+ch.id+ext;nextAssets.set(item.assetPrefix+audioName,{data:result.audio.data,mime:result.audio.mime});}ch.audioName=audioName;ch.filename='rec-'+ch.id+'.mc';item.charts.push(ch);item.activeChartId=ch.id;item.expanded=true;DCProject.activate(next,item.id);next.view={position:0,bottomBeat:null};const validated=DCProject.normalize(next);await dbPut([['assets',[...nextAssets]],['session',validated]]);beforeChange();pause();cancelAnalysis();session=validated;assets=nextAssets;libraryRevision++;nativeDirty.add(item.id);librarySignature='';selection.clear();position=0;loadedAudioName='';audioBuffer=null;analysis=null;gridSignature='';rebuildCaches();await loadChartAssets();changed();flushSave();return ch.id;}}).catch(err=>toast('REC 实验室未能打开：'+err.message));};

$('playLabBtn').onclick=()=>{if(!ready||!mutationAllowed())return;pause();DCProject.sync(session);DCPlayLab.open({esc,header,open:openModal,toast,skin:()=>skin,audio:getAudio,previewPrefs:()=>C.clone(settings()),calibrationSound:async()=>({buffer:await beatPlayer.prepare(settings().beatSound),prefs:C.clone(settings().beatSound)}),volume:()=>settings().volume,currentSong:()=>session.activeSongId,currentChart:()=>session.activeChartId,songs:()=>session.songs.map(s=>({id:s.id,title:s.song.title,charts:s.charts})),media:(id,ch)=>{const item=session.songs.find(s=>s.id===id);if(!item)return null;const media=new Map(songAssets(item)),dir=(ch.filename||'').includes('/')?ch.filename.slice(0,ch.filename.lastIndexOf('/')+1):'',resolve=name=>name&&(media.get(dir+name)||media.get(name)||[...media].find(([key])=>key.split('/').pop()===name.split('/').pop())?.[1]);return{audio:resolve(ch.audioName),background:resolve(ch.backgroundName),buffer:loadedAudioName===item.assetPrefix+ch.audioName?audioBuffer:null};}}).catch(e=>toast('试玩实验室无法打开：'+e.message));};
